#include <windows.h>
#include <gdiplus.h>
#include "next/integration/session.hpp"
#include "engine/mechanism_layout.hpp"
#include <iostream>
using namespace r62;using namespace core;
int main(){Gdiplus::GdiplusStartupInput in;ULONG_PTR token;Gdiplus::GdiplusStartup(&token,&in,0);{integration::Session s;auto e=s.open("work/test-r14-current/projection-mechanism-0-0-0.cdxml");for(const auto& ar:s.doc.arrows().records())if(ar.isAlive())s.doc.removeObject(ObjectRef(ObjectKind::Arrow,ar.id));ObjectId base=kInvalidObjectId,h=kInvalidObjectId;for(const auto& a:s.doc.atoms().records())if(a.isAlive()){if(mechanism::genericRole(s.doc,a.id)=="base"&&a.semantics.charge<0)base=a.id;if(a.element==1&&projection_molecule::coreFor(s.doc,a.id)!=kInvalidObjectId)h=a.id;}Vec2 a=s.doc.atoms().alive(base)->position,b=s.doc.atoms().alive(h)->position;auto p=arrows::resolvePreset(49,a,b,.6);p.mechanism=true;p.electronSource={ObjectKind::Atom,base};p.electronTarget={ObjectKind::Atom,h};p.sourceVisualAnchor=2;p.targetVisualAnchor=1;p.mechanismSide=1;p.arcSagitta=length(b-a)*.85;arrows::routeMechanism(s.doc,p,true);auto points=arrows::routedPoints(p);auto obstacles=arrows::mechanismObstacles(s.doc);int collisions=0;for(auto q:points)for(const auto& o:obstacles)if(o.glyphOwner.valid()&&o.glyphOwner!=p.electronSource&&o.glyphOwner!=p.electronTarget&&arrows::mechanismObstacleDistance(q,o)<.6)++collisions;std::cout<<"glyph collisions "<<collisions<<"\n";std::cout<<"begin "<<p.begin.x<<' '<<p.begin.y<<" end "<<p.end.x<<' '<<p.end.y<<"\n";auto cross=[](Vec2 a,Vec2 b,Vec2 c){auto u=b-a,v=c-a;return u.x*v.y-u.y*v.x;};for(size_t i=1;i<points.size();++i)for(const auto& edge:s.doc.bonds().records())if(edge.isAlive()){auto x=s.doc.atoms().alive(edge.beginAtom)->position,y=s.doc.atoms().alive(edge.endAtom)->position;if(cross(points[i-1],points[i],x)*cross(points[i-1],points[i],y)<-1e-8&&cross(x,y,points[i-1])*cross(x,y,points[i])<-1e-8)std::cout<<"cross "<<edge.id<<" endpoints "<<x.x<<' '<<x.y<<" to "<<y.x<<' '<<y.y<<" curve "<<points[i-1].x<<' '<<points[i-1].y<<" to "<<points[i].x<<' '<<points[i].y<<"\n";}}Gdiplus::GdiplusShutdown(token);}
